# Code generated by Claude
"""
Render the simulated cameras once from the spawn pose and save PNGs.

No stepping: qpos is set to the spawn position and mj_forward is called, so
the images show the robot at its initial configuration.

Usage:
    python experiments/camera_snapshot.py
    python experiments/camera_snapshot.py --scene models/scenes/other.xml
    python experiments/camera_snapshot.py --spawn -1 3.5 0.22
"""

import argparse
import sys
from pathlib import Path

import cv2
import mujoco

PROJECT_ROOT = Path(__file__).resolve().parent.parent
sys.path.insert(0, str(PROJECT_ROOT))

from src import robot_specs
from src.cameras import CameraRig
from src.simulator import RobotSimulator

DEFAULT_SCENE = "models/scenes/chemistry_lab_combined.xml"
DEFAULT_SPAWN = [-1.0, 3.5, 0.22]
OUT_DIR = PROJECT_ROOT / "data" / "camera_snapshots"


def main():
    parser = argparse.ArgumentParser()
    parser.add_argument("--scene", default=DEFAULT_SCENE)
    parser.add_argument("--spawn", type=float, nargs=3, default=DEFAULT_SPAWN,
                        metavar=("X", "Y", "Z"))
    args = parser.parse_args()

    sim = RobotSimulator(model_path=str(PROJECT_ROOT / args.scene),
                         cameras=robot_specs.CAMERA_SPECS)
    model, data = sim.model, sim.data
    data.qpos[0:3] = args.spawn
    mujoco.mj_forward(model, data)

    # Sim choice: a hidden GL context at the offscreen size, since there is
    # no GLFW viewer window here.
    gl = mujoco.GLContext(model.vis.global_.offwidth, model.vis.global_.offheight)
    gl.make_current()
    context = mujoco.MjrContext(model, mujoco.mjtFontScale.mjFONTSCALE_150)

    rig = CameraRig(model, robot_specs.CAMERA_SPECS, context)
    rig.render(data)

    OUT_DIR.mkdir(parents=True, exist_ok=True)
    for name, img in rig.images.items():
        path = OUT_DIR / f"{name}.png"
        cv2.imwrite(str(path), cv2.cvtColor(img, cv2.COLOR_RGB2BGR))
        print(f"Saved {path}  {img.shape[1]}x{img.shape[0]}")


if __name__ == "__main__":
    main()
